import 'package:cloud_firestore/cloud_firestore.dart';
import 'model_utils.dart';
class StudentModel { const StudentModel({required this.userId,this.educationLevel,this.institution,this.gpa,this.skillIds=const [],this.interestIds=const [],this.subjectGrades=const {}}); final String userId; final String? educationLevel,institution; final double? gpa; final List<String> skillIds,interestIds; final Map<String,num> subjectGrades;
factory StudentModel.fromFirestore(DocumentSnapshot<Map<String,Object?>> doc)=>StudentModel.fromMap(doc.id,doc.data()??{}); factory StudentModel.fromMap(String id,Map<String,Object?> m)=>StudentModel(userId:id,educationLevel:m['educationLevel'] as String?,institution:m['institution'] as String?,gpa:(m['gpa'] as num?)?.toDouble(),skillIds:stringsFrom(m['skillIds']),interestIds:stringsFrom(m['interestIds']),subjectGrades:numbersFrom(m['subjectGrades'])); Map<String,Object?> toFirestore()=>{'educationLevel':educationLevel,'institution':institution,'gpa':gpa,'skillIds':skillIds,'interestIds':interestIds,'subjectGrades':subjectGrades}; }
